'use client';

import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { InlineSheet } from '@/registry/ndeko/ui/inline-sheet';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { AppHeader } from './app-header';
import { Composer } from './composer';
import { KEPT_LINE, RECEIVERS, seedOf, SHARED_LINE } from './data';
import { MemoPanel } from './memo-panel';
import {
  INITIAL,
  isOver,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  sendableTextOf,
  SHARE_MS,
  type Decision,
  type ResearchState,
  type Stage,
} from './session';
import { peopleOf } from './share-request';
import { Thread } from './thread';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The width of the `@3xl` container variant: under it the memo lives in a sheet. */
const SHEET_BELOW_REM = 48;

function placeholderOf(stage: Stage) {
  if (stage === 'idle') {
    return 'Ask a question about your workspace';
  }
  if (stage === 'asking') {
    return 'Allow or deny the request above';
  }
  if (isOver(stage)) {
    return 'Ask a follow-up';
  }
  return 'Researcher is working';
}

function announcementOf(stage: Stage) {
  if (stage === 'researching') {
    return 'Researcher is reading the workspace';
  }
  if (stage === 'answered') {
    return 'The answer and the memo are ready';
  }
  if (stage === 'asking') {
    const people = peopleOf(RECEIVERS.length);
    return `Researcher asks to share the memo with ${people}. Allow or deny it`;
  }
  if (stage === 'shared') {
    return SHARED_LINE;
  }
  if (stage === 'kept') {
    return KEPT_LINE;
  }
  return '';
}

function stepInProgressOf(state: ResearchState) {
  const running = state.activity.find((run) => run.status === 'running');
  if (!running) {
    return null;
  }
  const seed = seedOf(running.id);
  return seed.title;
}

/** Nothing calls a network. A real agent plugs in here: what a person sends, and their answer to the request to share. */
export type Application10Props = {
  onSend?: (text: string) => void;
  onApprove?: () => void;
  onDeny?: () => void;
};

export default function Application10({
  onSend,
  onApprove,
  onDeny,
}: Application10Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const isNarrow = useIsNarrow(ref, SHEET_BELOW_REM);
  const { stage } = state;
  const sendableText = sendableTextOf(state);
  const canSend = sendableText !== null;
  const canReplay = isFinished && !isAutoplaying;
  const isSheetShown = isNarrow && state.isSheetOpen;
  const isMemoBeingWritten = state.sectionsStarted > state.sectionsDone;
  const announcement = announcementOf(stage);
  const message = spokenUnless(isAutoplaying, announcement);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function send() {
    if (sendableText === null) {
      return;
    }
    act({ type: 'sent' });
    onSend?.(sendableText);
  }

  /** The two buttons leave with the request, so the focus goes to what replaces them: the line that says what was decided. */
  function decide(decision: Decision) {
    act({ type: 'decided', decision });
    focusLater('[data-request]');
    if (decision === 'denied') {
      onDeny?.();
      return;
    }
    schedule(() => act({ type: 'shared' }), SHARE_MS);
    onApprove?.();
  }

  function openSheet() {
    act({ type: 'sheet', isOpen: true });
    focusLater('[data-sheet-close="memo"]');
  }

  function closeSheet() {
    act({ type: 'sheet', isOpen: false });
    focusLater('[data-memo-open]');
  }

  const memo = {
    stage,
    sectionsStarted: state.sectionsStarted,
    sectionsDone: state.sectionsDone,
    foldedSections: state.foldedSections,
    pressed,
    isActive: isInView,
    onToggleSection: (id: string) => act({ type: 'sectionToggled', id }),
  };

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='relative flex h-dvh min-h-[40rem] flex-col overflow-hidden'>
          <div inert={isSheetShown} className='flex min-h-0 flex-1 flex-col'>
            <AppHeader
              stage={stage}
              costUsd={state.costUsd}
              isMemoBeingWritten={isMemoBeingWritten}
              canReplay={canReplay}
              onReplay={restart}
              onOpenMemo={openSheet}
            />
            <div className='flex min-h-0 flex-1'>
              <main className='flex min-w-0 flex-1 flex-col'>
                <Thread
                  state={state}
                  pressed={pressed}
                  isActive={isInView}
                  onDecide={decide}
                />
                <div className='mx-auto w-full max-w-2xl shrink-0 px-4 pb-4'>
                  <Composer
                    draft={state.draft}
                    placeholder={placeholderOf(stage)}
                    canSend={canSend}
                    isSendPressed={pressed === 'send'}
                    onDraftChange={(text) => act({ type: 'typed', text })}
                    onSend={send}
                  />
                </div>
              </main>
              <aside
                aria-label='Memo'
                className='hidden w-[22rem] shrink-0 pe-3 pb-3 @3xl:flex @4xl:w-[26rem]'
              >
                <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-h-0 flex-1 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
                  {!isNarrow && (
                    <MemoPanel
                      {...memo}
                      stepInProgress={null}
                      className='w-full'
                    />
                  )}
                </div>
              </aside>
            </div>
          </div>

          <InlineSheet
            name='memo'
            label='Memo'
            closeLabel='Close the memo'
            side='bottom'
            closer='grip'
            isOpen={isSheetShown}
            className='@3xl:hidden'
            panelClassName='h-[80%] px-4 pb-4'
            onClose={closeSheet}
          >
            {/* The thread is out of sight under the sheet, so the sheet says which step is running. */}
            {isNarrow && (
              <MemoPanel
                {...memo}
                stepInProgress={stepInProgressOf(state)}
                className='flex-1'
              />
            )}
          </InlineSheet>
          <LiveRegion message={message} />
        </div>
      </div>
    </ClockGate>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { MODEL, WORKSPACE } from './data';
import type { Stage } from './session';

const STATUS_WORD: Record<Stage, string> = {
  idle: 'Ready',
  researching: 'Researching',
  answering: 'Answering',
  answered: 'Answered',
  asking: 'Waiting on you',
  sharing: 'Sharing',
  shared: 'Done',
  kept: 'Done',
};

const STATUS_WORDS = Object.values(STATUS_WORD);

const STATUS_DOT: Record<Stage, string> = {
  idle: 'bg-muted-foreground/45',
  researching: 'bg-info',
  answering: 'bg-info',
  answered: 'bg-info',
  asking: 'bg-warning',
  sharing: 'bg-info',
  shared: 'bg-success',
  kept: 'bg-success',
};

const LIVE_STAGES: Stage[] = ['researching', 'answering', 'sharing'];

/** Under a dollar a cost keeps three decimals, as in the rest of the kit. */
const COST_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  minimumFractionDigits: 3,
  maximumFractionDigits: 3,
};

function pulseOf(stage: Stage) {
  if (LIVE_STAGES.includes(stage)) {
    return 'animate-pulse';
  }
  return undefined;
}

type AppHeaderProps = {
  stage: Stage;
  costUsd: number;
  isMemoBeingWritten: boolean;
  canReplay: boolean;
  onReplay: () => void;
  onOpenMemo: () => void;
};

export function AppHeader({
  stage,
  costUsd,
  isMemoBeingWritten,
  canReplay,
  onReplay,
  onOpenMemo,
}: AppHeaderProps) {
  return (
    <header className='flex shrink-0 flex-wrap items-center gap-x-3 gap-y-2 px-4 py-2.5'>
      <div className='flex min-w-40 flex-1 items-center gap-2.5'>
        <CompanyMark seed={WORKSPACE.name} size='lg' />
        <div className='flex min-w-0 flex-col leading-tight'>
          <h1 className='truncate text-sm font-medium'>
            {WORKSPACE.name}
            <span className='text-muted-foreground font-normal'>
              {' '}
              / {WORKSPACE.space}
            </span>
          </h1>
          <p className='text-muted-foreground flex items-center gap-1.5 text-xs'>
            <span
              aria-hidden='true'
              className={cn(
                'size-1.5 shrink-0 rounded-full transition-colors duration-200',
                STATUS_DOT[stage],
                pulseOf(stage)
              )}
            />
            <WordRoll text={STATUS_WORD[stage]} labels={STATUS_WORDS} />
          </p>
        </div>
      </div>
      <div className='flex flex-wrap items-center gap-2'>
        <ReplayButton isShown={canReplay} onReplay={onReplay} label='Replay' />
        <span className='flex items-center gap-1.5 text-xs'>
          <BrandTile brand={MODEL.brand} />
          <span className='sr-only @sm:not-sr-only'>{MODEL.name}</span>
        </span>
        <span className='flex items-center gap-1.5 text-xs'>
          <span className='sr-only'>Cost of this run</span>
          <MotionNumber
            value={costUsd}
            format={COST_FORMAT}
            className='font-medium'
          />
          <Badge variant='secondary'>Illustrative</Badge>
        </span>
        <Button
          type='button'
          variant='outline'
          size='sm'
          data-memo-open
          aria-haspopup='dialog'
          onClick={onOpenMemo}
          className='@3xl:hidden'
        >
          {isMemoBeingWritten && (
            <span
              aria-hidden='true'
              className='bg-info size-1.5 rounded-full'
            />
          )}
          Memo
        </Button>
      </div>
    </header>
  );
}

'use client';

import { useFollowBottom } from '@/registry/ndeko/hooks/use-follow-bottom';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import { ActivityTimeline } from './activity-timeline';
import { CitedAnswer } from './cited-answer';
import { FOLLOW_UP_REPLY, RESEARCHER } from './data';
import { hasReached, type Decision, type ResearchState } from './session';
import { ShareRequest } from './share-request';

function ResearcherTile() {
  const color = seriesColorOf(RESEARCHER.series);

  return <MeshTile seed={RESEARCHER.name} color={color} size='lg' />;
}

function PersonBubble({ text }: { text: string }) {
  return (
    <p className='bg-foreground/[0.06] max-w-[85%] self-end rounded-2xl rounded-ee-md px-3.5 py-2 text-sm leading-relaxed'>
      {text}
    </p>
  );
}

function FollowUp({ text }: { text: string }) {
  return (
    <>
      <PersonBubble text={text} />
      <div className='flex items-start gap-2.5'>
        <ResearcherTile />
        <p className='text-muted-foreground min-w-0 flex-1 pt-1 text-sm leading-relaxed'>
          {FOLLOW_UP_REPLY}
        </p>
      </div>
    </>
  );
}

type ThreadProps = {
  state: ResearchState;
  pressed: string | null;
  isActive: boolean;
  onDecide: (decision: Decision) => void;
};

export function Thread({ state, pressed, isActive, onDecide }: ThreadProps) {
  const { scrollerRef, contentRef, updatePinned } = useFollowBottom();
  const { stage, question } = state;
  const hasQuestion = question !== null;
  const showsAnswer = hasReached(stage, 'answering');
  const showsRequest = hasReached(stage, 'asking');

  return (
    <div
      ref={scrollerRef}
      onScroll={updatePinned}
      className='min-h-0 flex-1 overflow-y-auto'
    >
      <div
        ref={contentRef}
        className='mx-auto flex min-h-full w-full max-w-2xl flex-col gap-5 px-4 py-5'
      >
        {!hasQuestion && (
          <p className='text-muted-foreground m-auto max-w-xs text-center text-[13px] leading-relaxed'>
            Ask a question about the workspace. Each step shows here while the
            memo is written in its panel.
          </p>
        )}
        {question && <PersonBubble text={question} />}
        {hasQuestion && (
          <div className='flex items-start gap-2.5'>
            <ResearcherTile />
            <div className='flex min-w-0 flex-1 flex-col gap-3'>
              <span className='sr-only'>{RESEARCHER.name}</span>
              <ActivityTimeline
                activity={state.activity}
                isResearching={stage === 'researching'}
                startedAt={state.startedAt}
                endedAt={state.endedAt}
              />
              {showsAnswer && (
                <CitedAnswer
                  isStreaming={stage === 'answering'}
                  isActive={isActive}
                  demoLitSource={state.demoLitSource}
                />
              )}
              {showsRequest && (
                <ShareRequest
                  stage={stage}
                  pressed={pressed}
                  onDecide={onDecide}
                />
              )}
            </div>
          </div>
        )}
        {state.followUps.map((text, index) => (
          <FollowUp key={index} text={text} />
        ))}
      </div>
    </div>
  );
}

'use client';

import { useId, useState } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { elapsedOf, formatDuration } from '@/registry/ndeko/lib/agent-run';
import {
  BrainIcon,
  ChevronDownIcon,
  CompassIcon,
  FileTextIcon,
  SearchIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { countOf } from '@/registry/ndeko/lib/words';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { CallStatusMark } from '@/registry/ndeko/ui/call-status';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { LiveDuration } from '@/registry/ndeko/ui/live-duration';

import { seedOf, type ActivityKind, type ActivitySeed } from './data';
import type { ActivityRun } from './session';

const KIND_WORD: Record<ActivityKind, string> = {
  think: 'Think',
  search: 'Search',
  read: 'Read',
};

const KIND_ICON: Record<ActivityKind, Icon> = {
  think: BrainIcon,
  search: SearchIcon,
  read: FileTextIcon,
};

function KindTile({ seed }: { seed: ActivitySeed }) {
  if (seed.brand) {
    return <BrandTile brand={seed.brand} size='lg' title={seed.product} />;
  }
  const KindIcon = KIND_ICON[seed.kind];

  return (
    <span
      aria-hidden='true'
      className='keycap-3d text-muted-foreground inline-flex size-7 shrink-0 items-center justify-center rounded-md'
    >
      <KindIcon className='size-3.5' />
    </span>
  );
}

function sublineOf(seed: ActivitySeed, run: ActivityRun) {
  if (run.status === 'done') {
    return seed.doneSummary;
  }
  return seed.detail;
}

type ActivityRowProps = {
  run: ActivityRun;
  isLast: boolean;
};

function ActivityRow({ run, isLast }: ActivityRowProps) {
  const seed = seedOf(run.id);
  const isRunning = run.status === 'running';
  const subline = sublineOf(seed, run);

  return (
    <li className='relative flex gap-2.5 pb-3 transition-[opacity,translate] duration-300 ease-(--ease-out-strong) last:pb-0 starting:translate-y-1 starting:opacity-0'>
      {!isLast && (
        <span
          aria-hidden='true'
          className='bg-border absolute start-3.5 top-8 bottom-1 w-px'
        />
      )}
      <KindTile seed={seed} />
      <div className='flex min-w-0 flex-1 flex-col'>
        <p className='flex h-7 items-center gap-2 text-[13px]'>
          <span className='min-w-0 truncate font-medium'>{seed.title}</span>
          <CallStatusMark status={run.status} />
          <LiveDuration
            item={run}
            isRunning={isRunning}
            className='text-muted-foreground ms-auto w-10 shrink-0 text-end text-xs'
          />
        </p>
        <p className='text-muted-foreground min-h-5 text-xs leading-5'>
          <span className='text-foreground/70'>{KIND_WORD[seed.kind]}</span>
          <span aria-hidden='true'> · </span>
          <span
            key={run.status}
            className='transition-opacity duration-300 starting:opacity-0'
          >
            {subline}
          </span>
        </p>
      </div>
    </li>
  );
}

function headlineOf(isResearching: boolean, duration: string) {
  if (isResearching) {
    return 'Researching';
  }
  return `Researched in ${duration}`;
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return 'rotate-0';
}

type ActivityTimelineProps = {
  activity: ActivityRun[];
  isResearching: boolean;
  startedAt?: number;
  endedAt?: number;
};

/** Open while the agent works, then folded into one line that says how long the research took. */
export function ActivityTimeline({
  activity,
  isResearching,
  startedAt,
  endedAt,
}: ActivityTimelineProps) {
  const [openChoice, setOpenChoice] = useState<boolean | null>(null);
  const [wasResearching, setWasResearching] = useState(isResearching);
  const panelId = useId();
  const span = { startedAt, endedAt };
  const elapsed = elapsedOf(span, endedAt ?? 0);
  const duration = formatDuration(elapsed);
  const headline = headlineOf(isResearching, duration);
  const lastIndex = activity.length - 1;

  if (wasResearching !== isResearching) {
    setWasResearching(isResearching);
    setOpenChoice(null);
  }

  const isOpen = openChoice ?? isResearching;

  function toggle() {
    setOpenChoice(!isOpen);
  }

  return (
    <div className='bg-foreground/[0.03] dark:bg-foreground/[0.05] rounded-xl p-1.5'>
      <button
        type='button'
        aria-expanded={isOpen}
        aria-controls={panelId}
        onClick={toggle}
        className='hover:bg-foreground/[0.04] focus-visible:ring-ring/25 flex h-8 w-full cursor-pointer items-center gap-2 rounded-lg px-2 text-start text-[13px] outline-none focus-visible:ring-[3px]'
      >
        <CompassIcon className='text-muted-foreground size-4 shrink-0' />
        <span className='min-w-0 truncate font-medium'>
          <WordRoll text={headline} />
        </span>
        {isResearching && (
          <LiveDuration
            item={span}
            isRunning
            className='text-muted-foreground w-10 text-xs'
          />
        )}
        <span className='text-muted-foreground ms-auto shrink-0 text-xs tabular-nums'>
          {countOf(activity.length, 'step')}
        </span>
        <ChevronDownIcon
          className={cn(
            'text-muted-foreground size-3.5 shrink-0 transition-transform duration-200 ease-(--ease-out-strong)',
            chevronTurnOf(isOpen)
          )}
        />
      </button>
      <Fold open={isOpen} id={panelId}>
        <ol
          aria-label='Research steps'
          className='flex flex-col px-2 pt-2 pb-1.5'
        >
          {activity.map((run, index) => (
            <ActivityRow key={run.id} run={run} isLast={index === lastIndex} />
          ))}
        </ol>
      </Fold>
    </div>
  );
}

'use client';

import { Fragment, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { leadingSpaceOf } from '@/registry/ndeko/lib/words';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import {
  inkClassOf,
  shownCountOf,
  StreamCaret,
  useRevealedCount,
} from '@/registry/ndeko/ui/streamed-text';

import { ANSWER_TOKENS, SOURCES, type AnswerToken, type Source } from './data';
import { ANSWER_WORD_MS } from './session';

const FALLBACK_SOURCE = SOURCES[0];

function sourceOf(number: number) {
  const source = SOURCES.find((candidate) => candidate.number === number);
  return source ?? FALLBACK_SOURCE;
}

function isCiteOf(token: AnswerToken, number: number) {
  return token.kind === 'cite' && token.source === number;
}

/** A source shows under the answer once its first mark has streamed in. */
function firstMarkOf(source: Source) {
  return ANSWER_TOKENS.findIndex((token) => isCiteOf(token, source.number));
}

function litOverlayOf(isLit: boolean) {
  if (isLit) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

function litTextOf(isLit: boolean) {
  if (isLit) {
    return 'text-primary-ink';
  }
  return 'text-muted-foreground';
}

function toggledPin(current: number | null, number: number) {
  if (current === number) {
    return null;
  }
  return number;
}

type CitationMarkProps = {
  source: Source;
  isShown: boolean;
  isStreaming: boolean;
  isLit: boolean;
  isPinned: boolean;
  onHover: (number: number | null) => void;
  onPin: (number: number) => void;
};

function CitationMark({
  source,
  isShown,
  isStreaming,
  isLit,
  isPinned,
  onHover,
  onPin,
}: CitationMarkProps) {
  function light() {
    onHover(source.number);
  }

  function dim() {
    onHover(null);
  }

  function pin() {
    onPin(source.number);
  }

  return (
    <button
      type='button'
      aria-pressed={isPinned}
      aria-label={`Source ${source.number}: ${source.title}, ${source.product}`}
      onPointerEnter={light}
      onPointerLeave={dim}
      onFocus={light}
      onBlur={dim}
      onClick={pin}
      className={cn(
        'keycap-3d focus-visible:ring-ring/25 relative ms-1 inline-flex h-4 min-w-4 cursor-pointer items-center justify-center rounded-[4px] px-1 align-[0.12em] text-[10px] leading-none font-medium tabular-nums transition-colors duration-150 outline-none focus-visible:ring-[3px]',
        litTextOf(isLit),
        inkClassOf(isStreaming, isShown)
      )}
    >
      <span
        aria-hidden='true'
        className={cn(
          'bg-primary/15 pointer-events-none absolute inset-0 rounded-[inherit] transition-opacity duration-150',
          litOverlayOf(isLit)
        )}
      />
      <span className='relative'>{source.number}</span>
    </button>
  );
}

type SourcePillProps = {
  source: Source;
  isShown: boolean;
  isStreaming: boolean;
  isLit: boolean;
};

function SourcePill({ source, isShown, isStreaming, isLit }: SourcePillProps) {
  return (
    <li
      className={cn(
        'bg-foreground/[0.05] relative flex h-7 max-w-full items-center gap-1.5 overflow-hidden rounded-full ps-1 pe-1.5 text-xs',
        inkClassOf(isStreaming, isShown)
      )}
    >
      <span
        aria-hidden='true'
        className={cn(
          'bg-primary/12 pointer-events-none absolute inset-0 transition-opacity duration-150',
          litOverlayOf(isLit)
        )}
      />
      <BrandTile
        brand={source.brand}
        title={source.product}
        className='relative rounded-full'
